public enum LuaLoadMode
    {
        /// <summary>A fresh map has started. Calls <c>init()</c>.</summary>
        NewGame = 0,

        /// <summary>A save game has been loaded. Calls <c>load(false)</c>.</summary>
        LoadSave = 1,

        /// <summary>A map has been opened in the Map Editor. Calls <c>load(true)</c>.</summary>
        LoadMapEditor = 2,

        /// <summary>A lord AI script is being initialized standalone (no map init code present).</summary>
        AILord = 3,
    }

public enum LuaNoesisInjectionMode
{
    /// <summary> Adds the new XAML as a child of the target element. </summary>
    Child = 0,
    /// <summary> Replaces the content of the target element. </summary>
    ReplaceContent = 1,
    /// <summary> Adds the new XAML to the PARENT of the target element. (Useful for unnamed root grids). </summary>
    AddToParent = 2
}
